  ["a9aef1f838939d17"] = { "いつの日か、あなたのAllianceへの貢献も、今日目にした英雄たちに並ぶほど大きなものになるでしょう。彼らに敬意を払いなさい、{name}。", "." },
  ["a9b36d68e4d56fc8"] = { "Barrens北東部に、汚染で病んだ水のたまりがあります。地元の者はそこをSludge Fenと呼んでいます。Venture Companyが、かつて水晶のように青かった水を、工業廃棄物と汚物の泥沼に変えてしまったのです。その沼の中心に、あなたの求めるものがあります、{name}。\n\n気をつけてください。Venture Companyは侵入者を許しませんし、自分たちのために働いていない者はすべて侵入者と見なします。自然を守る者であるあなたは、とりわけ標的になるでしょう。彼らが激しく敵視しているものですから。", "." },
  ["a9b87d301a976fc7"] = { "Drek'Tharは、AlteracにおけるFrostwolf Clanの軍事的かつ精神的な指導者であり、Frostwolf Keepから同胞を率いている。\n\n奴が倒されれば、AlteracのHorde軍は崩れ去るだろう。", "." },
  ["a9b9cf43457121bc"] = { "%sはScepter of the Shifting SandsをFandral Staghelmに手渡した。", "." },
  ["a9ba3752bcbfce77"] = { "戦の時は目前だ、{class}！HordeもAllianceも準備を終えた。我々の戦争物資は今まさにSilithusへ運ばれている。残りも一日のうちには届くだろう。すべてが向こうに揃い、Scepter of the Shifting Sandsを苦労の末に組み上げた者がそれをScarab Gongに打ち鳴らせば、Ahn'Qirajの門が開かれる。そして幾時代も見られなかったほどの戦いが始まるのだ！\n\nLok'tar Ogar！", "." },
